document.addEventListener("DOMContentLoaded",function(){const t=document.querySelector(".menu-toggle"),e=document.querySelector(".nav");if(t&&e){t.addEventListener("click",function(){e.classList.toggle("active"),t.setAttribute("aria-expanded",e.classList.contains("active"))});document.querySelectorAll(".nav-link").forEach(function(n){n.addEventListener("click",function(){e.classList.remove("active"),t.setAttribute("aria-expanded","false")})}),document.addEventListener("click",function(n){e.contains(n.target)||t.contains(n.target)||(e.classList.remove("active"),t.setAttribute("aria-expanded","false"))})}const n=window.location.pathname.split("/").pop()||"index.html";document.querySelectorAll(".nav-link").forEach(function(t){const e=t.getAttribute("href");(e===n||""===n&&"index.html"===e)&&t.classList.add("active")});document.querySelectorAll('a[href^="#"]').forEach(function(t){t.addEventListener("click",function(t){const e=this.getAttribute("href");if("#"===e)return;const n=document.querySelector(e);n&&(t.preventDefault(),n.scrollIntoView({behavior:"smooth",block:"start"}))})});document.querySelectorAll('a[href*="wa.me"]').forEach(function(t){t.addEventListener("click",function(){console.log("WhatsApp contact clicked")})})});